let data,selectedTicker='AAPL',range=252,currentView='overview',metricPartition='test';
const names={AAPL:'Apple Inc.',MSFT:'Microsoft Corporation',NVDA:'NVIDIA Corporation',AMZN:'Amazon.com, Inc.',TSLA:'Tesla, Inc.'};
const featureNames={price_only:'Price only',price_news:'Price + news',price_reddit:'Price + Reddit',sentiment_only:'Sentiment only',combined:'Combined',matched_sample:'Matched baseline'};
const titles={overview:['A clearer view of the signal.','Financial sentiment, tested against the market. Every baseline included.','Overview'],market:['The market, in context.','A shared historical timeline for five liquid US equities.','Market data'],models:['Measure against the baseline.','Inspect development results. Keep the final test separate.','Model benchmarks'],results:['An honest result.','Frozen evaluation, paired uncertainty and a reproducible handoff.','Final results'],pipeline:['From hypothesis to evidence.','A reproducible, chronological experiment. Honest about every gap.','Project pipeline']};
const activeMetrics=()=>metricPartition==='test'&&data?.testMetrics?data.testMetrics:data.metrics;
const $=id=>document.getElementById(id),fmt=x=>x==null?'—':x.toFixed(3),usd=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(x),dateLabel=x=>new Date(x+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
function view(name){currentView=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!=='view-'+name);document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===name));$('page-title').textContent=titles[name][0];$('page-description').textContent=titles[name][1];$('breadcrumb').textContent=titles[name][2];location.hash=name;if(name==='overview'){metricPartition='test';$('metric-partition').value='test';if(data)filtered();renderChart();}window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1);if(titles[name]&&name!==currentView)view(name)});
$('notice-details').onclick=()=>view('pipeline');$('all-benchmarks').onclick=()=>view('models');
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('export-button').onclick=()=>{if(!data)return;const keys=['model_id','feature_set','roc_auc','f1','accuracy','precision','recall'];download('sentiment-lab-'+metricPartition+'.csv',[keys.join(','),...activeMetrics().map(m=>keys.map(k=>m[k]??'').join(','))].join('\n'),'text/csv');};
$('download-prices').onclick=()=>download('sentiment-lab-prices.csv',['ticker,date,vendor_close,volume',...Object.entries(data.prices).flatMap(([ticker,rows])=>rows.map(r=>`${ticker},${r.date},${r.close},${r.volume}`))].join('\n'),'text/csv');
function renderStocks(){const tabs=$('stock-tabs');tabs.replaceChildren();for(const [ticker,rows] of Object.entries(data.prices)){const last=rows.at(-1),previous=rows.at(-2),change=(last.close/previous.close-1)*100,b=document.createElement('button');b.className='stock-tab'+(ticker===selectedTicker?' selected':'');b.setAttribute('aria-pressed',String(ticker===selectedTicker));b.innerHTML=`${ticker}<span class="mini-change">${change>=0?'+':''}${change.toFixed(2)}%</span>`;b.onclick=()=>{selectedTicker=ticker;renderStocks();renderChart()};tabs.append(b)}
 $('stocks-table').innerHTML=`<table><thead><tr><th>EQUITY</th><th>COMPANY</th><th>LAST CLOSE</th><th>OBSERVATIONS</th><th>DATE RANGE</th></tr></thead><tbody>${Object.entries(data.prices).map(([ticker,rows])=>`<tr><td>${ticker}</td><td>${names[ticker]}</td><td class="metric-value">${usd(rows.at(-1).close)}</td><td>${rows.length.toLocaleString()}</td><td>${dateLabel(rows[0].date)} — ${dateLabel(rows.at(-1).date)}</td></tr>`).join('')}</tbody></table>`;
}
function renderChart(){if(!data)return;const rows=data.prices[selectedTicker].slice(-range),last=rows.at(-1),change=(last.close/rows[0].close-1)*100; $('stock-name').textContent=names[selectedTicker];$('current-price').textContent=usd(last.close);$('period-change').textContent=`${change>=0?'+':''}${change.toFixed(2)}% this period`;$('period-change').classList.toggle('negative',change<0);
 const W=850,H=270,left=3,right=65,top=20,bottom=35,low=Math.min(...rows.map(r=>r.close)),high=Math.max(...rows.map(r=>r.close)),pad=(high-low)*.12||1,min=low-pad,max=high+pad;
 const x=i=>left+i/(rows.length-1)*(W-left-right),y=v=>top+(max-v)/(max-min)*(H-top-bottom),points=rows.map((r,i)=>`${x(i).toFixed(2)},${y(r.close).toFixed(2)}`),line='M'+points.join(' L'),area=line+` L${x(rows.length-1)},${H-bottom} L${left},${H-bottom} Z`;
 let grid='';for(let i=0;i<5;i++){const value=min+(max-min)*i/4,py=y(value);grid+=`<line x1="${left}" x2="${W-right+10}" y1="${py}" y2="${py}" stroke="#edf2ee" stroke-dasharray="3 5"/><text x="${W-right+20}" y="${py+4}" fill="#9aaa9e" font-size="10">$${value.toFixed(0)}</text>`}
 let dates='';for(let n=0;n<4;n++){let i=Math.round((rows.length-1)*n/3);dates+=`<text x="${x(i)}" y="${H-6}" fill="#9aaa9e" font-size="10" text-anchor="${n===0?'start':n===3?'end':'middle'}">${new Date(rows[i].date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',year:'2-digit'})}</text>`}
 $('price-chart').innerHTML=`<defs><linearGradient id="price-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3da98e" stop-opacity=".15"/><stop offset="100%" stop-color="#3da98e" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${area}" fill="url(#price-fill)"/><path d="${line}" fill="none" stroke="#298e78" stroke-width="2.3" stroke-linejoin="round"/><circle cx="${x(rows.length-1)}" cy="${y(last.close)}" r="4" fill="#298e78" stroke="white" stroke-width="2"/>${dates}<line id="hover-line" x1="0" x2="0" y1="${top}" y2="${H-bottom}" stroke="#80b4a3" stroke-dasharray="3 4" opacity="0"/>`;
 const svg=$('price-chart'),tip=$('chart-tooltip');svg.onpointermove=e=>{const rect=svg.getBoundingClientRect(),pos=(e.clientX-rect.left)/rect.width*W,i=Math.max(0,Math.min(rows.length-1,Math.round((pos-left)/(W-left-right)*(rows.length-1)))),v=rows[i];tip.hidden=false;tip.textContent=`${dateLabel(v.date)} · ${usd(v.close)}`;const line=$('hover-line');line.setAttribute('x1',x(i));line.setAttribute('x2',x(i));line.setAttribute('opacity','1')};svg.onpointerleave=()=>{tip.hidden=true;$('hover-line')?.setAttribute('opacity','0')};}
$('ranges').querySelectorAll('button').forEach(b=>b.onclick=()=>{range=+b.dataset.range;$('ranges').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));renderChart()});
function modelName(m){if(m.family==='logistic_regression')return 'Logistic Regression';if(m.family==='random_forest')return 'Random Forest';return {training_majority:'Training majority',always_up:'Always up',zero_drift_no_change:'No-change forecast',momentum:'Momentum'}[m.model_id.split(':')[1]]||'Seeded coin · '+m.model_id.split('_').at(-1)}
function table(rows,target){$(target).innerHTML=`<table><thead><tr><th>MODEL</th><th>FEATURE SET</th><th>ROC-AUC</th><th>F1-SCORE</th><th>ACCURACY</th><th>PARTITION</th></tr></thead><tbody>${rows.map(m=>`<tr data-model="${m.model_id}" tabindex="0" role="button" aria-label="Inspect ${modelName(m)}, ${featureNames[m.feature_set]}"><td><span class="model-mark">${m.family==='logistic_regression'?'LR':m.family==='random_forest'?'RF':'B'}</span>${modelName(m)}</td><td><span class="feature-label ${m.family==='baseline'?'baseline-label':''}">${featureNames[m.feature_set]||'Baseline'}</span></td><td class="metric-value">${fmt(m.roc_auc)}</td><td class="metric-value">${fmt(m.f1)}</td><td>${(m.accuracy*100).toFixed(1)}%</td><td>${metricPartition==='test'?'Held-out test':'Validation'}</td></tr>`).join('')||'<tr><td colspan="6">No comparisons match these filters.</td></tr>'}</tbody></table>`;$(target).querySelectorAll('[data-model]').forEach(el=>{el.onclick=()=>details(el.dataset.model);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();details(el.dataset.model)}}})}
function filtered(){let family=$('family-filter').value,features=$('feature-filter').value,include=$('include-baselines').checked;table(activeMetrics().filter(m=>(family==='all'?(m.family!=='baseline'||include):m.family===family)&&(features==='all'||m.feature_set===features)&&(m.family!=='baseline'||!m.model_id.includes('coin_seed_')||m.model_id.endsWith('coin_seed_42'))),'full-table')}
['family-filter','feature-filter','include-baselines'].forEach(id=>$(id).onchange=filtered);
$('metric-partition').onchange=()=>{metricPartition=$('metric-partition').value;filtered()};
function details(id){const m=activeMetrics().find(x=>x.model_id===id),c=m.confusion_matrix;$('dialog-content').innerHTML=`<h2>${modelName(m)}</h2><p>${featureNames[m.feature_set]||'Baseline'} · ${m.rows} ${metricPartition==='test'?'held-out':'validation'} observations. The sentiment data gate remains unmet.</p><div class="dialog-metrics"><div><strong>${fmt(m.roc_auc)}</strong><span>ROC-AUC</span></div><div><strong>${fmt(m.f1)}</strong><span>F1-score</span></div><div><strong>${(m.accuracy*100).toFixed(1)}%</strong><span>Accuracy</span></div></div><h3>Confusion matrix</h3><div class="dialog-confusion"><div>True non-up<strong>${c[0][0]}</strong></div><div>False up<strong>${c[0][1]}</strong></div><div>False non-up<strong>${c[1][0]}</strong></div><div>True up<strong>${c[1][1]}</strong></div></div><p>Positive-class prevalence: ${(m.positive_prevalence*100).toFixed(1)}%. Classification threshold: 0.5.</p>${m.parameters?'<h3>Selected parameters</h3><pre>'+JSON.stringify(m.parameters,null,2)+'</pre>':''}<p>No eligible sentiment data is present. This comparison cannot establish sentiment’s incremental predictive value.</p>`;$('detail-dialog').showModal()}
$('close-dialog').onclick=()=>$('detail-dialog').close();$('detail-dialog').onclick=e=>{if(e.target===$('detail-dialog'))$('detail-dialog').close()};$('help-button').onclick=()=>{$('dialog-content').innerHTML='<h2>An honest research dashboard.</h2><p>This website displays a saved snapshot from the Stock Sentiment Lab project. It includes real historical vendor prices and actual validation / frozen held-out results from trained classifiers.</p><p>NewsAPI and Reddit history are not connected. Sentiment remains missing, and held-out evaluation cannot answer the sentiment-value question. No live quotes, trade recommendations or profitability claims are provided.</p><p>The full experiment is reproducible from the Python project and frozen model artifacts.</p>';$('detail-dialog').showModal()};
fetch('data.json').then(r=>{if(!r.ok)throw Error('Unable to load research data');return r.json()}).then(result=>{data=result;$('stat-prices').textContent=Object.values(data.prices).reduce((n,r)=>n+r.length,0).toLocaleString();$('stat-rows').textContent=data.features.retained_rows.toLocaleString();$('stat-models').textContent=data.summary.trained_models;$('stat-test').textContent=data.summary.holdout_rows_reserved;$('asof').textContent='As of '+dateLabel(data.asOf);renderStocks();renderChart();table([activeMetrics().find(m=>m.model_id==='logistic_regression:price_only'),activeMetrics().find(m=>m.model_id==='random_forest:price_only'),activeMetrics().find(m=>m.model_id==='baseline:always_up'),activeMetrics().find(m=>m.model_id==='baseline:momentum')].filter(Boolean),'preview-table');filtered();$('milestones').innerHTML=data.milestones.map(m=>`<div class="milestone ${m.done?'done':''}"><span class="milestone-marker">${m.done?'✓':m.id}</span><div><strong>${m.id} · ${m.title}</strong><small>${m.done?'Implemented and verified':m.id==='M6'?'Next: frozen held-out evaluation and paired uncertainty':'Final report, data cards and demonstration'}</small></div><span class="source-tag ${m.done?'available':'pending'}">${m.done?'Complete':'Upcoming'}</span></div>`).join('');$('freeze-id').textContent='Freeze ID: '+data.freezeId;if(data.evaluation){$('result-auc').textContent=data.evaluation.primary_control_metrics.roc_auc.toFixed(4);$('result-delta').textContent=data.evaluation.primary_delta_auc.estimate.toFixed(4);$('result-ci').textContent='['+data.evaluation.primary_delta_auc.interval.map(x=>x.toFixed(4)).join(', ')+']';$('result-conclusion').textContent=data.conclusion.statement;}const initial=location.hash.slice(1);if(titles[initial])view(initial)}).catch(error=>{$('loading-error').hidden=false;$('loading-error').textContent='Research data could not be loaded. Please refresh the page. '+error.message});
